# -*- coding: utf-8 -*-
# Plain-voice rewrite of the driver report text and the market context, using sources read on 8-9 November 2026.
p = '_build_driver_report_nov2.py'; s = open(p, encoding='utf-8').read()
def rep(old, new, count=1):
    global s
    if old not in s: raise SystemExit('missing: ' + old[:80])
    s = s.replace(old, new, count)

# ---- opening ----
i = s.index("add(f'<div class=\"key\">This report explains"); j = s.index("\n", i)
s = s[:i] + "add(f'<div class=\"key\">This report explains how the forecast moves and why. It covers total sales: every rate class and every customer, whether or not a key account manager handles it. FY2027 comes to {TT[27]:,.1f} GWh and FY2028 to {TT[28]:,.1f}, against the plan\\'s {TH27:,.1f} and {TH28:,.1f}. FY2026 is our outlook: billed sales to October plus our forecast for November and December, {TT[26]:,.1f} GWh, {abs(TT[26] - le26):,.1f} GWh below the financials\\' {le26:,.1f} (Section 11).</div>')" + s[j:]

# ---- section 1 notes ----
rep("FY2025 includes the storm months of November and December. YoY on FY2026 is flattered by the storm-depressed first half of 2026, which is why FY2027 growth reads high; Section 2 separates it.",
    "FY2025 includes the storm months of November and December. FY2027 growth reads high because the first half of 2026 was storm-depressed; Section 2 separates that out.")
rep("RT50 is the largest difference ({sgn(T[\"RT50\"][27] - H27[\"RT50\"], 0)} GWh in FY2027, {sgn(T[\"RT50\"][28] - H28[\"RT50\"], 0)} in FY2028): the plan lifts the whole class for storm recovery, we recover hotels property by property. RT70 is {sgn(T[\"RT70\"][27] - H27[\"RT70\"], 0)} GWh in FY2027, about 5 GWh of it from taking MBJ at 47% off rather than the KAM\\'s 77%.",
    "RT50 is the biggest gap ({sgn(T[\"RT50\"][27] - H27[\"RT50\"], 0)} GWh in FY2027, {sgn(T[\"RT50\"][28] - H28[\"RT50\"], 0)} in FY2028). The plan lifts the whole class for storm recovery; we recover hotels property by property. RT70 is {sgn(T[\"RT70\"][27] - H27[\"RT70\"], 0)} GWh in FY2027, about 5 GWh of it because we take MBJ at 47% off and the KAM has 77%.")
rep("It was not storm-affected and its volume rose through 2026, so it gets no storm recovery and only the commercial growth rate. Its October kWh were flat on September; the J$174M revenue credit it carries is a monthly revenue item with no kWh effect.",
    "It was not hit by the storm and its volume rose through 2026, so it gets no storm recovery, only commercial growth. October kWh were flat on September. The J$174M revenue credit on its bill is a monthly revenue item and does not change the kWh.")

# ---- market context table, after the RT50 excluding cement block (before section 2) ----
mk = """
add('<h3>What the market is telling us</h3><table><colgroup><col style="width:13%"><col style="width:50%"><col style="width:37%"></colgroup><tr><th class="l">Item</th><th class="l">What we have read</th><th class="l">In the forecast</th></tr>')
MK = [('Hotel rooms', 'About 70% of the storm-hit room stock was back by 14 September. More than 11,000 rooms return through 2027: just over 1,900 in December (Sandals Montego Bay, Sandals Royal Caribbean, Iberostar Rose Hall, Bahia Principe) and just under 3,500 in the first quarter of 2027 (Hyatt Ziva and Zilara Rose Hall, Secrets, Breathless, Jewel Grande, Catalonia). Tortuga Resorts said on 8 November it is spending over US$400m, with reopenings from the first quarter of 2027.', 'Recovery follows that schedule: 19% of each hotel\\'s gap to pre-storm in January 2027, 75% by December, 80% by the end of 2028. Hotels below 30% of pre-storm get nothing until a date is confirmed (Section 10).'),
      ('Reopening dates', 'They have slipped. Sandals Montego Bay, Royal Caribbean and South Coast were due on 30 May 2026, and the Hyatt Inclusive group on 1 November 2026 (TravelPulse, February).', 'Ten points less recovery all year takes ' + f'{gap_all_m * 0.1 * 12:.1f}' + ' GWh off. The KAMs are giving us dates by property.'),
      ('Economy', 'The PIOJ said on 19 August that output could be back at its pre-Melissa level as early as April to June 2027, sooner than it expected.', 'No commercial growth until April 2027, then 1% a year.'),
      ('Alumina', 'Century Aluminum brought a new turbine (TG4) online at Jamalco in early August. The refinery now runs entirely on its own power and reached full capacity by the end of July (Gleaner, 9 August).', 'Alcoa (Jamalco) goes to zero from November. A standby load of 0.26 GWh a month would add about 3 GWh a year.'),
      ('New load', 'PriceSmart opened its Montego Bay club on 1 October and will open South Camp Road in Kingston in December (Observer, 4 November).', 'Montego Bay is in from November and Kingston from January 2027, at the 258 and 268 MWh a month the KAM entered.'),
      ('Solar policy', 'Government plans a further 100 MW of distributed solar through a strengthened net billing programme, and has opened talks with JPS on a higher net billing threshold and battery storage.', 'Not in the base. Every 10 MW would take about 14 to 15 GWh a year off (Section 7).'),
      ('Weather', 'The WMO said on 3 September that El Ni\\u00f1o is firmly established, will strengthen to a very strong event peaking late in 2026 and is almost certain to last through February 2027.', 'No weather overlay. A warmer year would lift residential load; we hold it as upside (Section 6).')]
for a_, b_, c_ in MK: add(f'<tr><td class="l"><b>{a_}</b></td><td class="l" style="font-size:11px">{b_}</td><td class="l" style="font-size:11px">{c_}</td></tr>')
add('</table><div class="note">Sources and how far we checked them are listed in Section 11.</div>')
"""
rep("# ================= 2 and 3 =================", "HOTg = HOT[HOT.hotel_up27 > 0]; gap_all_m = float((HOTg.ps - HOTg.level).sum()) / 1e6" + mk + "\n# ================= 2 and 3 =================")

# ---- sections 2 and 3 ----
rep("One bar per driver, each starting where the last finished. There are no parent bars: the drivers shown are the whole movement and they sum to {sgn(sm)}. The axis does not start at zero. Drivers are measured account by account, not solved to a total, so there is no plug line.",
    "Each bar is one driver and starts where the last one finished. Together they make up the whole movement of {sgn(sm)}. Every driver is measured account by account, so none is a balancing figure. The axis does not start at zero.")
rep("Positive where that half was depressed, negative where a customer has already stepped down, as Alcoa has.", "Positive where that half was depressed, negative where a customer has already stepped down, as Alcoa has.")
rep("'Each hotel recovers part of its own gap to pre-storm: 30% of the gap in January 2027, 62% by December and 70% by December 2028. Section 10.'", "'Each hotel recovers part of its own gap to pre-storm, following the reopening schedule: 19% of the gap in January 2027, 75% by December and 80% by December 2028. Section 10.'")
rep("<div class=\"key\"><b>What is driving each class in this bridge.</b> By industry and customer, so the movement is not left as a class total.</div>", "<div class=\"key\"><b>What is driving each class.</b> The customers and industries behind each class movement:</div>")

# ---- section 4 ----
rep("Residential growth comes from two separate places and the forecast treats them separately. Premises join the grid, and households already on it cross into higher consumption bands. Premises added in FY2027 are worth about {EV[\"acq27\"]:.1f} GWh; the rest of the rise is the current run rate, which already holds every premise connected to October (Section 5). Confusing the two is what makes residential growth look either unexplained or overstated, so each is set out on its own.",
    "Residential growth comes from two places. New premises join the grid, and households already on it move into higher consumption bands. Premises added in FY2027 are worth about {EV[\"acq27\"]:.1f} GWh. The rest of the rise is the current run rate, which already includes every premise connected to October (Section 5). We show them separately because they are easy to mix up.")
rep("The window taken is the longer one because a shorter window is as likely to carry deferred connections catching up as a step change.", "We use the longer window. A short one can pick up deferred connections catching up and read as a faster rate than the base supports.")
rep("Premises connected is the right series because it reads through the storm. It fell by 3,325 in November 2025 and was above its October level by December.", "We use premises connected because it reads through the storm: it fell by 3,325 in November 2025 and was back above its October level by December.")

# ---- section 5 ----
rep("These are annual rates applied to the middle of August to October 2026, not monthly rates compounding against a rolling base, so what is stated is what the forecast carries. How the 0.8% reconciles to the evidence in Section 4:",
    "These are annual rates applied to the August to October run rate, so the rate shown is the growth the forecast carries. The 0.8% reconciles to the evidence in Section 4 like this:")
rep("The difference, {g27 - EV[\"acq_net\"]:+.0f} GWh, is the load decline in 5.3 net of migration into higher bands. Each 1% on RT10 is {T[\"RT10\"][27] / 100:.1f} GWh.", "The difference, {g27 - EV[\"acq_net\"]:+.0f} GWh, is the load decline in 5.3 net of households moving into higher bands. Each 1% on RT10 is {T[\"RT10\"][27] / 100:.1f} GWh.")
rep("We do not book it as a separate line: it sits inside the net 0.8% growth, where it offsets part of the premises growth in 4.3.", "We do not book it as a separate line. It sits inside the net 0.8% growth, where it offsets part of the premises growth in 4.3.")
rep("so the October step down is broad and seasonal, not a few customers.", "so the October step down is broad and seasonal and not down to a few customers.")

# ---- section 6 ----
i = s.index("add(f'<div class=\"gap\">The forecast carries no weather overlay."); j = s.index("\n", i)
s = s[:i] + "add(f'<div class=\"gap\">The forecast has no weather overlay. The previous report applied a forecast temperature anomaly against the 2023-2025 mean at 1.93% of residential load per degree Celsius, worth +7.1 GWh in FY2027. We have dropped it because we have no temperature outlook for Jamaica to support it and the platform holds no temperature series to test it against. The WMO\\'s view that a very strong El Ni\\u00f1o peaks late in 2026 and lasts into 2027 points to a warmer year, so we treat weather as upside.</div>')" + s[j:]
rep("This anomaly profile is carried from the previous report as the reference for sizing the upside. It is not a forecast of 2028 seasonality.", "This anomaly profile is carried over from the previous report only to size the upside. It says nothing about 2028.")

# ---- section 7 ----
rep("The forecast has no separate solar line. Residential solar erosion sits inside the net 0.8% growth (Section 5.3), and self-consumption, which never shows as export, is inferred rather than measured. Commercial solar is handled account by account: PAC (4 MW), MBJ (6 MW), Sutherland (100 kW) and the other KAM entries in Section 9.",
    "The forecast has no separate solar line. Residential solar erosion is inside the net 0.8% growth (Section 5.3), and self-consumption, which never shows as export, can only be inferred. Commercial solar is handled account by account: PAC (4 MW), MBJ (6 MW), Sutherland (100 kW) and the other KAM entries in Section 9.")
rep("and the government\\'s 100 MW distributed target would take roughly 14 to 15 GWh a year off for every 10 MW. Neither is in the base.", "and the Government\\'s plan for a further 100 MW of net billing would take roughly 14 to 15 GWh a year off for every 10 MW. It has also opened talks with JPS on a higher net billing threshold and battery storage. None of this is in the base.")

# ---- section 9 ----
rep("Defection here is a customer moving to its own generation, entered by the KAM and, where we have changed it, shown with the reason.", "Defection here means a customer moving to its own generation. The entries are the KAMs\\', and where we changed one the reason is shown. Alcoa in our data is Jamalco, where Century Aluminum brought a new turbine online in early August and the refinery now runs on its own power.")

# ---- section 10 ----
i = s.index("add(f'<p>We recover part of each property\\'s own gap"); j = s.index("add('<p>The earlier approach applied storm normalisation")
new10 = ("add(f'<p>The market gives us a schedule. About 70% of the affected rooms were back by mid-September, just over 1,900 more return in December and just under 3,500 in the first quarter of 2027, with the rest through 2027. We apply that to each property\\'s own gap to its pre-storm level, the average month of January to September 2025: 19% of the gap in January 2027, 40% by May, 75% by December and 80% by the end of 2028. Not all of a reopened room\\'s load comes back. Arrivals are still well down and a hotel that is not full still carries its fixed load, so we stop at 80%.</p>')\n"
         "add(f'<p>{n_rec} properties recover. {n_closed} are below 30% of their pre-storm level and get nothing until a KAM gives us a reopening date; the Tortuga rebuild from the first quarter of 2027 is the kind of date we are asking for. The gap across the properties that recover is {gap_m:.1f} GWh a month. Reopening dates have slipped before, so ten points less recovery all year would take {gap_m * 0.1 * 12:.1f} GWh off.</p>')\n")
s = s[:i] + new10 + s[j:]
i = s.index("add('<p>The earlier approach applied storm normalisation"); j = s.index("\n", i)
s = s[:i] + "add('<p>Before, we applied storm normalisation by rate class (RT50 at 4.66% a month, RT40 and RT20 smaller). It reached accounts the storm never touched and lifted RT50 by 24% in FY2027, which is why RT50 sits below the plan now. The property-by-property recovery above replaces it. RT10 needs none because its storm gap closed inside FY2026: it ran 12.5% and 15.4% below prior year in January and February, went above prior year in May and has been 3% to 5% above since July. Industrial carries none beyond hotels, after the class-wide adjustment was withdrawn on 29 August.</p>')" + s[j:]

# ---- section 11 ----
rep("<b>FY2027 and FY2028</b> are account-level projections. Each account starts from the middle of its August, September and October 2026 kWh (so one odd month does not drive it), shaped by", "<b>FY2027 and FY2028</b> are projected account by account. Each account starts from the median of its August, September and October 2026 kWh, so one odd month does not drive it, and is shaped by")
rep("Hotels recover as in Section 10. The KAM adjustments", "Hotels recover on the reopening schedule in Section 10. The KAM adjustments")
rep("The engine\\'s macro, weather, solar and storm-normalisation drivers are replaced by the explicit drivers in Sections 2 and 3, each measured account by account, so there is no plug and no overlay that cannot be traced. FY2027 moves from 3,439.6 to {TT[27]:,.1f} GWh and FY2028 from 3,514.8 to {TT[28]:,.1f}. In FY2027 RT50 and RT70 move most and RT10, RT20 and RT40 are within 5 GWh of the earlier figures.",
    "The engine\\'s macro, weather, solar and storm-normalisation drivers are replaced by the drivers in Sections 2 and 3, each measured account by account. FY2027 moves from 3,439.6 to {TT[27]:,.1f} GWh and FY2028 from 3,514.8 to {TT[28]:,.1f}. In FY2027 RT50 and RT70 move the most.")
rep("The KAMs are reviewing the forecast now; their changes will move this report.", "The KAMs are reviewing the forecast now and their changes will move this report.")
rep("add('<p><b>System losses</b> and the Sales &amp; Generation workbook are unchanged by this update; the workbook will carry these class totals once the KAM review closes.</p>')", """add('<p><b>System losses</b> and the Sales &amp; Generation workbook are unchanged by this update. The workbook will carry these class totals once the KAM review closes.</p>')
add('<h3>Sources</h3><p style="font-size:11px">Read in full: Jamaica Gleaner, 14 September 2026 (room stock and reopening schedule, Ministry of Tourism, JAPEX); TravelPulse, 15 February 2026 (original reopening dates); Jamaica Gleaner, 9 August 2026 (Jamalco TG4); WMO press release, 3 September 2026 (El Ni&ntilde;o). Headline and opening paragraph read: Jamaica Gleaner, 8 November 2026 (Tortuga Resorts); Jamaica Observer, 19 August 2026 (PIOJ) and 4 November 2026 (PriceSmart South Camp Road); PriceSmart Jamaica site (Montego Bay opening); Government of Jamaica renewable energy tender notice (net billing). Search summary only, to be opened before quoting outside the company: Caribbean Journal, 13 July 2026 (stayover arrivals); Rio Times (Sangster arrivals, August); Jamaica Observer, 25 September 2026 (Rusal and Windalco); JIS (MBJ solar); Jamaica Gleaner, 30 July 2026 (cement volumes).</p>')""")
open(p, 'w', encoding='utf-8').write(s); print('voice patch applied')
